# Generated by tools/sync_model.py from the AI team pipeline.
import os
import warnings
import cv2
import numpy as np

class VietOCR_DIP_Pipeline:
    def __init__(self):
        # CLAHE chỉ dùng cho ảnh bị mất nét (tương phản cực thấp)
        self.clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))

    def determine_skew(self, image):
        """Dùng thuật toán Projection Profile để tìm góc nghiêng"""
        # Angle estimation needs the page structure, not millions of pixels
        # rotated 60 times. Apply the chosen angle to the original image below.
        height, width = image.shape[:2]
        scale = min(1.0, 600 / width, 400 / height)
        if scale < 1:
            image = cv2.resize(image, None, fx=scale, fy=scale, interpolation=cv2.INTER_AREA)
        _, thresh = cv2.threshold(image, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)
        angles = np.arange(-15.0, 15.0, 0.5)
        scores = []
        for angle in angles:
            M = cv2.getRotationMatrix2D((thresh.shape[1]//2, thresh.shape[0]//2), angle, 1.0)
            rotated = cv2.warpAffine(thresh, M, (thresh.shape[1], thresh.shape[0]), flags=cv2.INTER_NEAREST)
            proj = np.sum(rotated, axis=1)
            score = np.sum((proj[1:] - proj[:-1]) ** 2)
            scores.append(score)
        best = max(scores)
        # Uniform/blank pages have tied scores; do not arbitrarily rotate -15°.
        return min((angle for angle, score in zip(angles, scores) if score == best), key=abs)

    def deskew(self, image):
        best_angle = self.determine_skew(image)
        if abs(best_angle) < 0.5:
            return image
            
        h_img, w_img = image.shape[:2]
        center = (w_img // 2, h_img // 2)
        M = cv2.getRotationMatrix2D(center, best_angle, 1.0)
        rotated = cv2.warpAffine(image, M, (w_img, h_img), 
                                 flags=cv2.INTER_CUBIC, borderMode=cv2.BORDER_CONSTANT, borderValue=255)
        return rotated

    def process_image(self, img_input):
        """
        Xử lý tiền kỳ bảo tồn. 
        Nhận đầu vào là đường dẫn ảnh (str) hoặc mảng Numpy (np.ndarray).
        """
        if isinstance(img_input, str):
            if not os.path.exists(img_input):
                warnings.warn(f"DIP Pipeline: File ảnh không tồn tại ở đường dẫn: {img_input}")
                return None
            img = cv2.imread(img_input, cv2.IMREAD_GRAYSCALE)
            if img is None:
                warnings.warn(f"DIP Pipeline: OpenCV không thể đọc được ảnh tại: {img_input}")
                return None
        elif isinstance(img_input, np.ndarray):
            if len(img_input.shape) == 3:
                img = cv2.cvtColor(img_input, cv2.COLOR_BGR2GRAY)
            else:
                img = img_input.copy()
        else:
            warnings.warn("DIP Pipeline: Định dạng ảnh đầu vào không hợp lệ. Hãy truyền Path (str) hoặc Numpy Array.")
            return None

        # 1. Deskew: Bắt buộc để VGG không bị trượt nét
        img = self.deskew(img)

        # 2. CLAHE có điều kiện: CHỈ cứu nét nếu ảnh thực sự quá mờ (Std < 30)
        if np.std(img) < 30:
            img = self.clahe.apply(img)

        return img



def split_text_lines(gray: np.ndarray) -> list[np.ndarray]:
    """Projection-based line segmentation for upright, single-column documents.

    Small components are kept so Vietnamese accents survive. This is deliberately
    a line splitter, not a general document-layout or scene-text detector.
    """
    import cv2
    height, width = gray.shape
    scale = min(1.0, 1600 / width)
    small = cv2.resize(gray, None, fx=scale, fy=scale) if scale < 1 else gray
    _, ink = cv2.threshold(small, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)
    count, labels, stats, _ = cv2.connectedComponentsWithStats(ink, connectivity=8)
    keep = np.zeros(count, dtype=bool)
    char_heights = []
    for label in range(1, count):
        _, _, component_width, component_height, area = stats[label]
        if area < 3 or component_height < 2:
            continue
        # Remove long page borders and rules from the projection.
        if component_height > small.shape[0] * 0.7 and component_width < 4:
            continue
        if component_width > small.shape[1] * 0.8 and component_height < 4:
            continue
        keep[label] = True
        if component_height >= 5:
            char_heights.append(component_height)
    clean = (keep[labels] * 255).astype(np.uint8)
    if not np.any(clean):
        return []

    typical_height = float(np.percentile(char_heights, 65)) if char_heights else 8.0
    rows = (np.count_nonzero(clean, axis=1) >= max(2, int(small.shape[1] * 0.0015))).astype(np.uint8)
    gap = max(3, int(typical_height * 0.45))
    rows = cv2.morphologyEx(rows[:, None], cv2.MORPH_CLOSE, np.ones((gap, 1), np.uint8)).ravel()
    changes = np.diff(np.pad(rows, (1, 1)).astype(np.int8))
    starts, ends = np.where(changes == 1)[0], np.where(changes == -1)[0]
    spans = [(int(top), int(bottom)) for top, bottom in zip(starts, ends) if bottom - top >= 3]
    lines = []
    for index, (top, bottom) in enumerate(spans):
        occupied = np.where(np.any(clean[top:bottom], axis=0))[0]
        if not len(occupied):
            continue
        pad = max(3, int((bottom - top) * 0.25))
        # Padding ends halfway into a gap, so it cannot include the next line.
        lower_limit = (spans[index - 1][1] + top) // 2 if index else 0
        upper_limit = (bottom + spans[index + 1][0]) // 2 if index + 1 < len(spans) else len(rows)
        y1 = max(lower_limit, top - pad)
        y2 = min(upper_limit, bottom + pad)
        x1, x2 = max(0, int(occupied[0]) - pad), min(small.shape[1], int(occupied[-1]) + pad + 1)
        lines.append(gray[max(0, int(y1 / scale)):min(height, int(y2 / scale)),
                          max(0, int(x1 / scale)):min(width, int(x2 / scale))].copy())
    return lines
